 demo:{title:'Notification card và modal',lead:'Badge neo vào card; modal bám viewport, có tên truy cập và quản lý focus.',html:S`<article class="card"><span class="badge">3</span><h2>Thông báo</h2><p>Bạn có ba bài tập mới.</p><button id="open" aria-haspopup="dialog" aria-controls="overlay">Xem chi tiết</button></article><div class="overlay" id="overlay" hidden><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><h2 id="modal-title">Bài tập tuần này</h2><p>Hoàn thiện profile card.</p><button id="close">Đóng</button></section></div>`,css:S`.card{position:relative;max-width:320px;padding:22px;border:1px solid #dbe3f0;border-radius:18px;background:white}.badge{position:absolute;right:-9px;top:-9px;display:grid;place-items:center;width:30px;height:30px;border-radius:50%;background:#ff667d;color:white}.overlay{position:fixed;inset:0;background:#17203aaa;z-index:90}.modal{position:fixed;left:50%;top:50%;transform:translate(-50%,-50%);width:min(360px,90%);padding:22px;border-radius:18px;background:white;z-index:100}`,js:S`var overlay=document.querySelector('#overlay');var openButton=document.querySelector('#open');var closeButton=document.querySelector('#close');function closeModal(){overlay.hidden=true;openButton.focus();}openButton.addEventListener('click',function(){overlay.hidden=false;closeButton.focus();});closeButton.addEventListener('click',closeModal);overlay.addEventListener('click',function(event){if(event.target===overlay)closeModal();});document.addEventListener('keydown',function(event){if(event.key==='Escape'&&!overlay.hidden)closeModal();});`,observe:'Badge giữ đúng góc; modal có accessible name, nhận focus khi mở và trả focus khi đóng.',size:'tall'},
